L30: class BaseInvoker {
L31:     buildCommand(options = {}) {
L32:         const env = options.env ?? process.env;
L33:         const override = env.AGENT_COMMAND_PATH;
L34:         return {
L35:             commandPath: override || this.command,
L36:             args: override
L37:                 ? (env.AGENT_ARGS ?? "").split(/\s+/).filter(Boolean).concat(commonArgs(options))
L38:                 : [...this.prefix, ...commonArgs(options)],
L39:             env: override
L40:                 ? { AGENT_COMMAND_PATH: override, AGENT_ARGS: env.AGENT_ARGS ?? this.prefix.join(" ") }
L41:                 : {},
L42:         };
L43:     }
L44:     invoke(options = {}) {
L45:         const cmd = this.buildCommand(options);
L46:         const cwd = options.env?.AGENT_CWD ?? process.cwd();
L47:         const env = { ...process.env, ...cmd.env, AGENT_STEWARD_CHILD_RUN: "1" };
L48:         // D-2.1: runner (local/docker/ssh) получает команду, spawn сохраняет cwd/env.
L49:         const invoke = (command, args) => new Promise((resolve, reject) => {
L50:             const child = spawn(command, args, { cwd, env, shell: false });
L51:             let stdout = "";
L52:             let stderr = "";
L53:             child.stdout?.on("data", (chunk) => { stdout += String(chunk); });
L54:             child.stderr?.on("data", (chunk) => { stderr += String(chunk); });
L55:             child.on("error", reject);
L56:             child.on("close", (code) => resolve({ exitCode: code ?? 1, stdout, stderr }));
L57:         });
L58:         return resolveRunner(options.runner)
L59:             .runner.execute({ command: cmd.commandPath, args: cmd.args, workdir: cwd, env }, invoke)
L60:             .then((result) => ({
L61:             exitCode: result.exitCode,
L62:             stdout: result.stdout ?? "",
L63:             stderr: result.stderr ?? "",
L64:         }));
L65:     }
L66: }
L67: /** OpenCode CLI — поведение по умолчанию, полностью совместимое с wrapper'ом. */
