    def.retryCount,
    def.retryDelay,
    def.qualityGate,
    def.nextTaskOnSuccess,
    def.nextTaskOnError,
    def.triggerType,
    def.watchPath,
    def.dependsOn,
    def.model,
    def.priority,
    def.beforeScript,
    def.afterScript,
    def.mcpEvent,
    def.workspaceId,
    def.allowedTools,
    def.deniedTools,
    def.matrix,
    def.matrixParentId,
    "create",
    def.timezone,
    def.notBefore,
    def.notAfter,
    def.pausedUntil,
    def.runAt,
