/** Метрики конкретной задачи, собранные из history.json. */
export interface TaskMetrics {
  total: number;
  success: number;
  error: number;
  /** Частичные выполнения: ответ получен, но проверка не прошла. */
  partial: number;
  /** Запуски в процессе (последняя запись — running, ещё не завершились). */
  running: number;
}

/** Агрегированная статистика по одной LLM-модели. */
export interface ModelAnalysis {
  model: string;
  totalRuns: number;
  totalTokens: number;
  totalCost: number;
  avgDuration: number;
  successRate: number;
}

/** Чтение JSON из переменной окружения с фолбэком на значение по умолчанию. */
function envJson<T>(name: string, fallback: T): T {
  const raw = process.env[name];
  if (!raw) return fallback;
  try {
    return JSON.parse(raw) as T;
  } catch {
    console.warn(
      `[scheduler] Неверный JSON в переменной ${name}, используются значения по умолчанию.`,
    );
    return fallback;
  }
}

/** Ручное переопределение цен: OPENCODE_SCHEDULER_MODEL_PRICES (JSON). */
const envModelPrices = envJson<Record<string, number>>(
  "OPENCODE_SCHEDULER_MODEL_PRICES",
  {},
);

/**
 * Цена модели за 1M токенов.
 *
 * Порядок: ручное переопределение → каталог цен OpenCode (models.dev) →
 * встроенная таблица → средняя оценка.
 */
export function modelPrice(model: string | undefined): number {
  const key = normalizeModelId(model);

  const override = envModelPrices[key];
  if (typeof override === "number" && Number.isFinite(override)) return override;

  const fromOpencode = catalogPricePerMillion(key);
  if (fromOpencode !== null) return fromOpencode;

  return DEFAULT_MODEL_PRICE_PER_MILLION[key] ?? DEFAULT_PRICE_PER_MILLION;
}

/** Оценка стоимости запуска по токенам (если точная цена неизвестна). */
function estimateCost(tokens: number, model: string | undefined): number {
  return (tokens * modelPrice(model)) / 1_000_000;
}

/**
 * Агрегирует историю по моделям и считает сценарии What-If.
 * Возвращает данные для GET /api/models-analysis и блока дашборда.
 */
export function aggregateModels(
  history: {
    status: string;
    durationMs: number;
    tokens?: number;
    costUsd?: number;
    model?: string;
  }[],
  /** Готовая What-If выборка. Без неё CLI не вызывается: только история и встроенный список. */
  whatIfSelection?: WhatIfSelection,
) {
  const map = new Map<
    string,
    { runs: number; success: number; tokens: number; cost: number; duration: number }
  >();

  let totalTokens = 0;
  let totalCost = 0;
  let totalRuns = 0;

  for (const record of history) {
    const model = (record.model ?? "").trim() || "по умолчанию";
    const tokens = Number(record.tokens) || 0;
    const cost =
      typeof record.costUsd === "number" && record.costUsd > 0
        ? record.costUsd
        : estimateCost(tokens, model === "по умолчанию" ? undefined : model);
    const duration = Number(record.durationMs) || 0;

    const item = map.get(model) ?? { runs: 0, success: 0, tokens: 0, cost: 0, duration: 0 };
    item.runs += 1;
    if (record.status === "success") item.success += 1;
    item.tokens += tokens;
    item.cost += cost;
    item.duration += duration;
    map.set(model, item);

    totalRuns += 1;
    totalTokens += tokens;
    totalCost += cost;
  }

  const models: ModelAnalysis[] = [...map.entries()]
    .map(([model, item]) => ({
      model,
      totalRuns: item.runs,
      totalTokens: item.tokens,
      totalCost: Number(item.cost.toFixed(6)),
      avgDuration: item.runs > 0 ? Math.round(item.duration / item.runs) : 0,
      successRate: item.runs > 0 ? Math.round((item.success / item.runs) * 100) : 0,
    }))
    .sort((a, b) => b.totalRuns - a.totalRuns);

  // What-If: сначала модели, которые реально запускались, затем по одной
  // модели на каждую цену из доступных в OpenCode. Явный список из
  // окружения главнее.
  const usedModels = models
    .map((item) => item.model)
    .filter((model) => model !== "по умолчанию");
  const envWhatIfModels = envJson<string[] | null>(
    "OPENCODE_SCHEDULER_WHAT_IF_MODELS",
    null,
  );
  const selection =
    Array.isArray(envWhatIfModels) && envWhatIfModels.length > 0
      ? { models: envWhatIfModels, source: "env" as const }
      : (whatIfSelection ?? selectWhatIfModels(usedModels, []));

  const whatIf = selection.models.map((model) => ({
    model,
    pricePerMillion: modelPrice(model),
    cost: Number(((totalTokens * modelPrice(model)) / 1_000_000).toFixed(4)),
  }));

  return {
    models,
    totals: { totalRuns, totalTokens, totalCost: Number(totalCost.toFixed(6)) },
    whatIf,
    whatIfSource: selection.source,
  };
}

